use anyhow::Result;
use clap::{Parser, Subcommand};
use std::path::PathBuf;
use std::net::SocketAddr;

mod server;
mod client;
mod stats;
mod util;

#[derive(Parser)]
#[command(name = "executable")]
#[command(about = "QUIC performance testing tool")]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand)]
enum Commands {
    /// Run as a perf server
    Server(ServerOpts),
    /// Run as a perf client
    Client(ClientOpts),
}

#[derive(Parser, Clone)]
struct ServerOpts {
    /// Address to listen on
    #[arg(long, default_value = "[::]:4433")]
    listen: String,

    /// TLS private key in DER format
    #[arg(short, long)]
    key: Option<PathBuf>,

    /// TLS certificate in PEM format
    #[arg(short, long)]
    cert: Option<PathBuf>,

    /// Send buffer size in bytes
    #[arg(long, default_value = "2M")]
    send_buffer_size: String,

    /// Receive buffer size in bytes
    #[arg(long, default_value = "2M")]
    recv_buffer_size: String,

    /// Whether to print connection statistics
    #[arg(long)]
    conn_stats: bool,

    /// Perform NSS-compatible TLS key logging
    #[arg(long)]
    keylog: bool,

    /// UDP payload size
    #[arg(long, default_value = "1200")]
    initial_mtu: u16,

    /// Disable packet encryption/decryption
    #[arg(long)]
    no_protection: bool,

    /// Initial round-trip-time (in msecs)
    #[arg(long)]
    initial_rtt: Option<u64>,

    /// Ack Frequency mode
    #[arg(long)]
    ack_frequency: bool,

    /// Congestion algorithm to use
    #[arg(long)]
    congestion: Option<String>,

    /// Stream receive window
    #[arg(long)]
    stream_receive_window: Option<String>,

    /// Connection receive window
    #[arg(long)]
    receive_window: Option<String>,

    /// Send window
    #[arg(long)]
    send_window: Option<String>,

    /// Max UDP payload size
    #[arg(long, default_value = "1472")]
    max_udp_payload_size: u16,

    /// qlog output file
    #[arg(long)]
    qlog: Option<PathBuf>,
}

#[derive(Parser, Clone)]
struct ClientOpts {
    /// Host to connect to
    #[arg(default_value = "localhost:4433")]
    host: String,

    /// Override DNS resolution for host
    #[arg(long)]
    ip: Option<String>,

    /// Specify the local socket address
    #[arg(long)]
    local_addr: Option<String>,

    /// Number of unidirectional requests
    #[arg(long, default_value = "0")]
    uni_requests: usize,

    /// Number of bidirectional requests
    #[arg(long, default_value = "1")]
    bi_requests: usize,

    /// Number of bytes to download
    #[arg(long, default_value = "1M")]
    download_size: String,

    /// Number of bytes to upload
    #[arg(long, default_value = "1M")]
    upload_size: String,

    /// Time to run in seconds
    #[arg(long, default_value = "60")]
    duration: u64,

    /// Interval for stats reporting
    #[arg(long, default_value = "1")]
    interval: u64,

    /// JSON output file
    #[arg(long)]
    json: Option<PathBuf>,

    /// Send buffer size
    #[arg(long, default_value = "2M")]
    send_buffer_size: String,

    /// Receive buffer size
    #[arg(long, default_value = "2M")]
    recv_buffer_size: String,

    /// Print connection statistics
    #[arg(long)]
    conn_stats: bool,

    /// Key logging
    #[arg(long)]
    keylog: bool,

    /// Initial MTU
    #[arg(long, default_value = "1200")]
    initial_mtu: u16,

    /// Disable protection
    #[arg(long)]
    no_protection: bool,

    /// Initial RTT
    #[arg(long)]
    initial_rtt: Option<u64>,

    /// Ack frequency
    #[arg(long)]
    ack_frequency: bool,

    /// Congestion algorithm
    #[arg(long)]
    congestion: Option<String>,

    /// Stream receive window
    #[arg(long)]
    stream_receive_window: Option<String>,

    /// Receive window
    #[arg(long)]
    receive_window: Option<String>,

    /// Send window
    #[arg(long)]
    send_window: Option<String>,

    /// Max UDP payload size
    #[arg(long, default_value = "1472")]
    max_udp_payload_size: u16,

    /// qlog file
    #[arg(long)]
    qlog: Option<PathBuf>,
}

#[tokio::main]
async fn main() -> Result<()> {
    init_tracing();

    let cli = Cli::parse();

    match cli.command {
        Commands::Server(opts) => server::run(opts).await?,
        Commands::Client(opts) => client::run(opts).await?,
    }

    Ok(())
}

fn init_tracing() {
    let subscriber = tracing_subscriber::fmt()
        .with_writer(std::io::stderr)
        .with_ansi(true)
        .with_target(true)
        .with_level(true)
        .pretty();

    tracing::subscriber::set_global_default(subscriber.finish())
        .expect("failed to set tracing subscriber");
}
