use anyhow::{anyhow, Result};

pub fn parse_size(size_str: &str) -> Result<usize> {
    let trimmed = size_str.trim().to_uppercase();

    // Try parsing as plain number first
    if let Ok(val) = trimmed.parse::<usize>() {
        return Ok(val);
    }

    // Parse with SI suffix
    let (num_part, suffix) = if let Some(idx) = trimmed.find(|c: char| c.is_alphabetic()) {
        (&trimmed[..idx], &trimmed[idx..])
    } else {
        return Err(anyhow!("invalid size format: {}", size_str));
    };

    let base: usize = num_part.parse()
        .map_err(|_| anyhow!("invalid number in size: {}", num_part))?;

    let multiplier = match suffix {
        "B" => 1,
        "KB" => 1_000,
        "MB" | "M" => 1_000_000,
        "GB" | "G" => 1_000_000_000,
        "KIB" => 1_024,
        "MIB" => 1_024 * 1_024,
        "GIB" => 1_024 * 1_024 * 1_024,
        _ => return Err(anyhow!("unknown size suffix: {}", suffix)),
    };

    Ok(base * multiplier)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_parse_size() {
        assert_eq!(parse_size("1000").unwrap(), 1000);
        assert_eq!(parse_size("1M").unwrap(), 1_000_000);
        assert_eq!(parse_size("1MB").unwrap(), 1_000_000);
        assert_eq!(parse_size("2M").unwrap(), 2_000_000);
        assert_eq!(parse_size("10G").unwrap(), 10_000_000_000);
    }
}
