        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_secs();

        Self {
            start: StartInfo {
                timestamp: Timestamp { timesecs: now },
            },
            intervals: Vec::new(),
        }
    }

    pub fn add_interval(&mut self, interval: Interval) {
        self.intervals.push(interval);
    }
