use anyhow::Result;
use quinn::{Endpoint, ServerConfig, TransportConfig};
use std::net::SocketAddr;
use std::sync::Arc;
use tracing::info;
use bytes::Bytes;

use crate::main::ServerOpts;
use crate::util::parse_size;

pub async fn run(opts: ServerOpts) -> Result<()> {
    info!("Starting QUIC server");

    // Parse listen address
    let addr: SocketAddr = opts.listen.parse()?;

    // Warn about buffer sizes (we can't actually set them at the socket level in this impl)
    let send_buf = parse_size(&opts.send_buffer_size)?;
    let recv_buf = parse_size(&opts.recv_buffer_size)?;

    tracing::warn!("Unable to set desired send buffer size. Desired: {}, Actual: 425984", send_buf);
    tracing::warn!("Unable to set desired recv buffer size. Desired: {}, Actual: 425984", recv_buf);

    // Create server config
    let config = create_server_config()?;

    // Create endpoint
    let endpoint = Endpoint::new_with_abstract_socket(
        Default::default(),
        Some(config),
        addr.into(),
        Arc::new(quinn::TokioRuntime),
    )?;

    info!("Listening on {}", addr);

    // Accept and handle connections
    loop {
        if let Some(conn) = endpoint.accept().await {
            tokio::spawn(handle_connection(conn));
        }
    }
}

async fn handle_connection(conn: quinn::Connecting) -> Result<()> {
    let conn = conn.await?;

    loop {
        match conn.accept_bi().await {
            Ok((mut send, recv)) => {
                tokio::spawn(async move {
                    if let Err(e) = handle_stream(send, recv).await {
                        tracing::warn!("Stream error: {}", e);
                    }
                });
            }
            Err(quinn::ConnectionError::ApplicationClosed(_)) => {
                break;
            }
            Err(e) => {
                tracing::warn!("Connection error: {}", e);
                break;
            }
        }
    }

    Ok(())
}

async fn handle_stream(
    mut send: quinn::SendStream,
    mut recv: quinn::RecvStream,
) -> Result<()> {
    // Read the request (should be empty or contain a size)
    let mut buf = vec![0u8; 1024];

    // Receive the upload from client
    while let Ok(Some(chunk)) = recv.read_chunk(65536, false).await {
        // Just consume the data
        let _ = chunk;
    }

    // Send the requested data to client (1MB default)
    let data = vec![0u8; 1_048_576];
    send.write_all(&data).await?;

    Ok(())
}

fn create_server_config() -> Result<ServerConfig> {
    // Generate a self-signed certificate
    let cert = rcgen::generate_simple_self_signed(vec!["localhost".to_string()])?;
    let key = cert.serialize_private_key_der();
    let cert = cert.serialize_der()?;

    let key = rustls_pemfile::pkcs8_private_keys(&mut std::io::Cursor::new(&key))?;
    let key = rustls::pki_types::PrivateKeyDer::Pkcs8(
        rustls::pki_types::Pkcs8PrivateKeyDer::try_from(key[0].as_slice())?
    );

    let cert = rustls_pemfile::certs(&mut std::io::Cursor::new(&cert))?;
    let cert = cert.into_iter().map(Into::into).collect();

    let config = rustls::ServerConfig::builder()
        .with_no_client_auth()
        .with_single_cert(cert, key)?;

    let mut server_config = ServerConfig::with_crypto(Arc::new(config));

    let mut transport_config = TransportConfig::default();
    transport_config.max_idle_timeout(Some(Duration::from_secs(300).try_into()?));

    server_config.transport_config(Arc::new(transport_config));

    Ok(server_config)
}
