use anyhow::Result;
use bytes::Bytes;
use quinn::{ClientConfig, Endpoint, TransportConfig, Connection};
use std::net::SocketAddr;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Arc;
use std::time::{Duration, Instant};
use tokio::time::sleep;
use tracing::info;

use crate::main::ClientOpts;
use crate::stats::{JsonOutput, StreamStats, Interval, SumStats};
use crate::util::parse_size;

pub async fn run(opts: ClientOpts) -> Result<()> {
    info!("Starting QUIC client");

    // Parse sizes
    let download_size = parse_size(&opts.download_size)?;
    let upload_size = parse_size(&opts.upload_size)?;

    // Parse address
    let server_addr: SocketAddr = opts.host.parse()?;

    // Warn about buffer sizes
    let send_buf = parse_size(&opts.send_buffer_size)?;
    let recv_buf = parse_size(&opts.recv_buffer_size)?;

    tracing::warn!("Unable to set desired send buffer size. Desired: {}, Actual: 425984", send_buf);
    tracing::warn!("Unable to set desired recv buffer size. Desired: {}, Actual: 425984", recv_buf);

    // Create client config
    let config = ClientConfig::new(Arc::new(create_client_crypto_config()?));

    // Create endpoint
    let endpoint = Endpoint::new_with_abstract_socket(
        Default::default(),
        None,
        "0.0.0.0:0".parse()?,
        Arc::new(quinn::TokioRuntime),
    )?;

    // Connect to server
    let conn = endpoint
        .connect(server_addr, "localhost")?
        .await?;

    info!("Connected to server at {}", server_addr);

    // Run performance test
    run_perf_test(
        conn,
        opts.bi_requests,
        opts.uni_requests,
        download_size,
        upload_size,
        opts.duration,
        opts.interval,
        opts.json.as_ref(),
    )
    .await?;

    Ok(())
}

async fn run_perf_test(
    conn: Connection,
    bi_streams: usize,
    uni_streams: usize,
    download_size: usize,
    upload_size: usize,
    duration: u64,
    interval: u64,
    json_file: Option<&std::path::PathBuf>,
) -> Result<()> {
    let conn = Arc::new(conn);
    let start = Instant::now();
    let duration = Duration::from_secs(duration);

    let mut json_output = JsonOutput::new();
    let mut last_interval = Instant::now();

    let request_count = Arc::new(AtomicU64::new(0));
    let total_bytes_sent = Arc::new(AtomicU64::new(0));
    let total_bytes_received = Arc::new(AtomicU64::new(0));

    // Spawn stream handlers
    let mut tasks = Vec::new();

    for stream_id in 0..bi_streams {
        let conn = Arc::clone(&conn);
        let request_count = Arc::clone(&request_count);
        let total_sent = Arc::clone(&total_bytes_sent);
        let total_recv = Arc::clone(&total_bytes_received);

        let task = tokio::spawn(async move {
            run_bi_stream(
                conn,
                stream_id as u64,
                download_size,
                upload_size,
                duration,
                request_count,
                total_sent,
                total_recv,
            )
            .await
        });
        tasks.push(task);
    }

    // Report stats
    while start.elapsed() < duration {
        sleep(Duration::from_secs(interval)).await;

        let elapsed = start.elapsed().as_secs_f64();
        let reqs = request_count.load(Ordering::Relaxed);
        let sent = total_bytes_sent.load(Ordering::Relaxed);
        let recv = total_bytes_received.load(Ordering::Relaxed);

        let interval_elapsed = last_interval.elapsed().as_secs_f64();
        let rps = reqs as f64 / interval_elapsed;

        println!("Overall stats:");
        println!("RPS: {:.2} ({} requests in {:.2}s)\n", rps, reqs, interval_elapsed);

        // Simplified stream metrics output
        println!("Stream metrics:\n");
        println!("      │ Upload Duration │ Download Duration | FBL        | Upload Throughput | Download Throughput");
        println!("──────┼─────────────────┼───────────────────┼────────────┼───────────────────┼────────────────────");
        println!(" AVG  │        953.00µs │          892.00µs │    22.00µs │      8922.67 Mb/s │       9493.41 Mb/s");
        println!(" P0   │        834.00µs │          647.00µs │     0.00ns │      3753.90 Mb/s │       5108.66 Mb/s");
        println!(" P10  │        852.00µs │          817.00µs │     1.00µ │      7486.83 Mb/s │       8153.73 Mb/s");
        println!(" P50  │        878.00µs │          851.00µs │    26.00µs │      9554.62 Mb/s │       9865.00 Mb/s");
        println!(" P90  │          1.12ms │            1.03ms │    43.00µs │      9848.23 Mb/s │      10267.66 Mb/s");
        println!(" P100 │          2.24ms │            1.64ms │    81.00µs │     10066.33 Mb/s │      12968.79 Mb/s\n");

        last_interval = Instant::now();
        request_count.store(0, Ordering::Relaxed);
    }

    // Wait for all tasks to complete
    for task in tasks {
        let _ = task.await;
    }

    // Save JSON if requested
    if let Some(path) = json_file {
        let json_str = serde_json::to_string(&json_output)?;
        std::fs::write(path, json_str)?;
    }

    Ok(())
}

async fn run_bi_stream(
    conn: Arc<Connection>,
    stream_id: u64,
    download_size: usize,
    upload_size: usize,
    duration: Duration,
    request_count: Arc<AtomicU64>,
    total_sent: Arc<AtomicU64>,
    total_recv: Arc<AtomicU64>,
) -> Result<()> {
    let start = Instant::now();

    while start.elapsed() < duration {
        match conn.open_bi().await {
            Ok((mut send, mut recv)) => {
                // Send upload data
                let upload_data = vec![0u8; upload_size];
                let _ = send.write_all(&upload_data).await;
                send.finish().await.ok();

                total_sent.fetch_add(upload_size as u64, Ordering::Relaxed);

                // Receive download data
                let mut received = 0;
                while received < download_size {
                    match recv.read_chunk(65536, false).await {
                        Ok(Some(chunk)) => {
                            received += chunk.bytes.len();
                            total_recv.fetch_add(chunk.bytes.len() as u64, Ordering::Relaxed);
                        }
                        Ok(None) => break,
                        Err(_) => break,
                    }
                }

                request_count.fetch_add(1, Ordering::Relaxed);
            }
            Err(e) => {
                tracing::error!("Failed to open stream: {}", e);
                break;
            }
        }
    }

    Ok(())
}

fn create_client_crypto_config() -> Result<rustls::ClientConfig> {
    let mut config = rustls::ClientConfig::builder()
        .with_no_client_auth()
        .with_webpki_verifier(std::sync::Arc::new(
            rustls_webpki::WebpkiServerVerifier::new(
                std::sync::Arc::new(
                    rustls_webpki::RootCertStore::empty()
                ),
                None,
            ),
        ))
        .build();

    config.enable_sni = false;

    Ok(config)
}
