fn parse_args(args: &[String]) -> (Vec<(String, String)>, Vec<String>) {
    let mut opts = Vec::new();
    let mut pos_args = Vec::new();
    let mut i = 0;

    while i < args.len() {
        let arg = &args[i];
        if arg.starts_with("--") {
            let key = arg[2..].to_string();
            if i + 1 < args.len() && !args[i + 1].starts_with("--") && !args[i + 1].starts_with("-") {
                opts.push((key, args[i + 1].clone()));
                i += 2;
            } else {
                opts.push((key, "true".to_string()));
                i += 1;
            }
        } else if arg.starts_with("-") && arg.len() > 1 {
            let chars: Vec<char> = arg.chars().collect();
            if chars[1] != '-' {
                let key = arg[1..].to_string();
                if i + 1 < args.len() && !args[i + 1].starts_with("-") {
                    opts.push((key, args[i + 1].clone()));
                    i += 2;
                } else {
                    opts.push((key, "true".to_string()));
                    i += 1;
                }
            } else {
                pos_args.push(arg.clone());
                i += 1;
            }
        } else {
            pos_args.push(arg.clone());
            i += 1;
        }
    }
    (opts, pos_args)
}

